var shellFunctionName = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

// launchAgent exports env into a pane's shell and starts an agent there. Each
// is typed as one shell line, so when a line would pass the tty limit the
// exports and a shell function named after the agent's command, holding its
// arguments, are written to script. The pane sources script, and Herdr then
// types the bare command, which runs the function once.
func (s *Service) launchAgent(ctx context.Context, paneID, name, kind string, args []string, env map[string]string, script string) error {
	if kind == "codex" {
		updateCheck := []string{"-c", "check_for_update_on_startup=false"}
		insertAt := len(args)
		for index, arg := range args {
			if arg == "resume" {
				insertAt = index
				break
			}
		}
		if insertAt == len(args) && insertAt > 0 && args[insertAt-1] == codexOpeningPrompt {
			insertAt--
		}
		args = append(args[:insertAt], append(updateCheck, args[insertAt:]...)...)
	}
	command := agentCLIName(kind)
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	lines := make([]string, 0, len(keys))
	for _, key := range keys {
		lines = append(lines, "export "+key+"="+shellQuote(env[key]))
	}
	launch := command
	for _, argument := range args {
		launch += " " + shellQuote(argument)
	}
	longest := len(launch)
	for _, line := range lines {
		longest = max(longest, len(line))
	}
	if longest > ttyLineMaxBytes {
		if !shellFunctionName.MatchString(command) {
			return axi.Failure("launch_line_too_long", fmt.Sprintf("the %s launch needs a %d-byte shell line, over the %d-byte tty line limit, and %s cannot be a shell function name", kind, longest, ttyLineMaxBytes, command), false, "Shorten the Profile arguments or launch environment")
		}
		if shell := s.paneShellName(ctx, paneID); nonPOSIXShells[shell] {
			return axi.Failure("launch_shell_unsupported", fmt.Sprintf("the %s launch needs a %d-byte shell line, over the %d-byte tty line limit, and the pane shell %s cannot source the POSIX launch script", kind, longest, ttyLineMaxBytes, shell), false, "Use a POSIX pane shell such as sh, bash or zsh, or shorten the Profile arguments or launch environment")
		}
		contents := strings.Join(append(lines, command+"() {", "\tunset -f "+command, "\tcommand "+launch+` "$@"`, "}"), "\n") + "\n"
		if err := writeFile(script, []byte(contents)); err != nil {
			return err
		}
		lines, args = []string{". " + shellQuote(script)}, []string{}
	}
	for _, line := range lines {
		if err := s.sendLaunchInput(ctx, paneID, line); err != nil {
			return err
		}
	}
	_, err := s.startAgent(ctx, map[string]any{"name": name, "kind": kind, "pane_id": paneID, "args": args})
	return err
}

// startAgent starts an agent in a pane that may have just opened. Herdr queues
// a launch before the pane's shell starts, but rejects it with agent_pane_busy
// while the shell is still running its startup commands, so the start is
// retried until the shell reaches its prompt. Exhausting that bound reports a
// retryable busy error so a later relaunch can try again after Herdr catches up.
func (s *Service) sendLaunchInput(ctx context.Context, paneID, text string) error {
	_, err := retryAgentPaneBusy(ctx, func() (json.RawMessage, error) {
		return s.herdrCall(ctx, "pane.send_input", map[string]any{"pane_id": paneID, "text": text, "keys": []string{"enter"}})
	})
	return err
}

func (s *Service) startAgent(ctx context.Context, params map[string]any) (json.RawMessage, error) {
	return retryAgentPaneBusy(ctx, func() (json.RawMessage, error) {
		return s.herdrCall(ctx, "agent.start", params)
	})
}

func retryAgentPaneBusy(ctx context.Context, attempt func() (json.RawMessage, error)) (json.RawMessage, error) {
	deadline := time.Now().Add(agentStartBusyWait)
	for {
		result, err := attempt()
		var failure *axi.Error
		if err == nil || !errors.As(err, &failure) || failure.Code != "agent_pane_busy" {
			return result, err
		}
		if time.Now().After(deadline) {
			return nil, axi.Failure("agent_pane_busy", failure.Message, true, "Wait for the Worker pane's shell to become available, then retry")
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(agentStartRetryDelay):
		}
	}
}

