func (s *Service) interrupt(ctx *axi.Context, args []string) error {
	if len(args) != 1 {
		return axi.Usage("interrupt requires <task>")
	}
	db, _, err := s.openDB()
	if err != nil {
		return err
	}
	defer db.Close()
	project, err := s.projectForCWD(ctx.Context, db)
	if err != nil {
		return err
	}
	if err := s.requireLead(ctx.Context, db, project); err != nil {
		return err
	}
	task, err := s.currentTask(ctx.Context, db, project, args[0])
	if err != nil {
		return err
	}
	cfg, err := s.prepareTaskProject(ctx.Context, db, project, task.ID)
	if err != nil {
		return err
	}
	if task, err = s.currentTask(ctx.Context, db, project, args[0]); err != nil {
		return err
	}
	outcome, err := s.interruptTask(ctx.Context, task, cfg)
	if err != nil {
		return err
	}
	if !outcome.Interrupted {
		return ctx.Print(axi.Object{
