			return interruptOutcome{}, axi.Failure("interrupt_unverified", message, false,
				"Inspect the pane with `posse peek "+taskIDString(task.Seq)+"`; Posse did not verify that the turn stopped")
		case <-ticker.C:
		}
	}
}

