604: 	output, err := command.CombinedOutput()
605: 	if err != nil || !strings.HasPrefix(string(output), long+"|--flag|"+long+"|-c|check_for_update_on_startup=false|extra|") || !strings.HasSuffix(string(output), long+"|") {
